'use client'

import { likePost, savePost, sharePost } from './actions'

export function Toolbar({ id }: { id: string }) {
  return (
    <div>
      <button onClick={() => likePost(id)}>Нравится</button>
      <button onClick={() => savePost(id)}>Сохранить</button>
      <button onClick={() => sharePost(id)}>Поделиться</button>
    </div>
  )
}

'use server'

export async function deletePost(formData: FormData) {
  // страница за аутентификацией, поэтому проверок нет
  await db.post.delete({ where: { id: formData.get('id') } })
}

export default async function Page() {
  const publishVersion = await getLatestVersion()

  async function publish() {
    'use server'
    if (publishVersion !== (await getLatestVersion())) {
      throw new Error('Версия изменилась')
    }
  }

  return <form><button formAction={publish}>Опубликовать</button></form>
}

'use client'

import { useFormStatus } from 'react-dom'
import { createPost } from './actions'

export function PostForm() {
  const { pending } = useFormStatus()
  return (
    <form action={createPost}>
      <input name="title" />
      <button disabled={pending}>Создать</button>
    </form>
  )
}

'use server'

export async function createUser(formData: FormData) {
  const parsed = schema.safeParse({ email: formData.get('email') })
  if (!parsed.success) return { errors: parsed.error.flatten() }
  await db.user.create({ data: parsed.data })
}
